@Test public void getInterfaceQualifiers() throws Exception { final String shader = "#version 320 es
" + "buffer coherent readonly restrict someblock {
" + " int a;
" + "};
"; final TranslationUnit tu = ParseHelper.parse(shader); final InterfaceBlock interfaceBlock = (InterfaceBlock) tu.getTopLevelDeclarations().get(0); assertEquals(4, interfaceBlock.getInterfaceQualifiers().size()); assertTrue(interfaceBlock.getInterfaceQualifiers().contains(TypeQualifier.BUFFER)); assertTrue(interfaceBlock.getInterfaceQualifiers().contains(TypeQualifier.COHERENT)); assertTrue(interfaceBlock.getInterfaceQualifiers().contains(TypeQualifier.READONLY)); assertTrue(interfaceBlock.getInterfaceQualifiers().contains(TypeQualifier.RESTRICT)); assertFalse(interfaceBlock.getInterfaceQualifiers().contains(TypeQualifier.UNIFORM)); assertFalse(interfaceBlock.getInterfaceQualifiers().contains(TypeQualifier.SHADER_INPUT)); assertFalse(interfaceBlock.getInterfaceQualifiers().contains(TypeQualifier.SHADER_OUTPUT)); assertFalse(interfaceBlock.getInterfaceQualifiers().contains(TypeQualifier.VOLATILE)); assertFalse(interfaceBlock.getInterfaceQualifiers().contains(TypeQualifier.WRITEONLY)); }

@Test public void testDeleteResultMetadata() throws Exception { Result result = new ResultImpl(true); result.setResultStatus(new ResultStatus(ResultStatus.STATUS.OK)); DeleteResultMetadata metadata = new DeleteResultMetadata(); metadata.addDeletedKey("key1"); metadata.addException("key2", new AuthorizationException()); result.setResultMetadata(metadata); String expected = "{
" + " "deleteResult" : [
"+ " {
" + " "deleted" : {
" + " "key" : "key1"
" + " }
" + " },
" + " {
" + " "error" : {
" + " "key" : "key2",
" + " "code" : 403,
" + " "message" : "org.apache.ambari.server.security.authorization.AuthorizationException:"+ " The authenticated user is not authorized to perform the requested operation"
" + " }
" + " }
" + "]
" + "}"; String json = new JsonSerializer().serialize(result).toString().replace("", ""); assertEquals(expected, json); }

@Test public void handlesCustomInlineSuffixes() { URL resource = getClass().getResource("idl-serialization/custom-inline-io.smithy"); Model model = Model.assembler().addImport(resource).assemble().unwrap(); Assertions.assertTrue(model.getShape(ShapeId.from("com.example#InlineOperationRequest")).isPresent()); Assertions.assertTrue(model.getShape(ShapeId.from("com.example#InlineOperationResponse")).isPresent()); Map<Path, String> reserialized = SmithyIdlModelSerializer.builder().inlineInputSuffix("Request").inlineOutputSuffix("Response").build().serialize(model); String modelResult = reserialized.values().iterator().next().replace("
", "
"); assertThat(modelResult, equalTo(IoUtils.readUtf8Url(resource).replace("
", "
"))); }
